tokens['version']=4;tokens['color']['themes']=[{'id':'light','name':'纸白 / Day'},{'id':'night','name':'石墨 / After hours'}];tokens['color']['tokens']=[{'name':n,'value':v,'usage':u} for n,v,u in newcolors];tokens['type']['families']['editorial']='Arial, "STILL Sans", sans-serif';tokens['radius']['tokens']=[{'name':'radius-none','value':'0px','usage':'纸面、包装、组件。'},{'name':'radius-small','value':'0px','usage':'行动按钮，方角。'},{'name':'radius-pill','value':'0px','usage':'风味信息不做胶囊。'}]
