# Update the helper's default palette without touching native template syntax.
_old_board=board
def board(name,title,w,h,inner,logic='return {};',props=None,bg=PAPER,pad=48):_old_board(name,title,w,h,inner,logic,props,bg,pad)
def rule(color=INK):return f'<div style="height:1px;background:{color};width:100%;flex-shrink:0"></div>'
def wordmark(size=42,color=INK):return f'<div style="display:flex;align-items:baseline;gap:20px;color:{color}"><span style="font:700 {size}px/.9 Arial,sans-serif;letter-spacing:-3px">[STILL]</span><span style="font-size:15px;letter-spacing:3px">隙间</span></div>'
def eyebrow(t,color=MUTED):return f'<div style="font:13px/1.5 monospace;letter-spacing:1px;color:{color}">{t}</div>'
def action(text,handler='',outline=False):return f'<button type="button" {handler} style="height:52px;padding:0 24px;border:1px solid {INK};background:{PAPER if outline else ORANGE};color:{INK};font-size:16px;font-weight:600;white-space:nowrap;cursor:pointer">{text}</button>'
def graphic(kind,color,width=340,height=200):
 out=f'<div style="position:relative;width:{width}px;height:{height}px;overflow:hidden">'
 if kind==1:
  for i in range(14):
   k=0.45+0.5*math.sin((i+1)/15*math.pi);lw=int((width-38)/2*k);y=8+i*(height-16)/14
   out+=f'<div style="position:absolute;left:{int((width-38)/2-lw)}px;top:{y:.1f}px;width:{lw}px;height:5px;background:{color}"></div><div style="position:absolute;left:{(width+38)/2}px;top:{y:.1f}px;width:{lw}px;height:5px;background:{color}"></div>'
 elif kind==2:
  for i in range(8):
   offset=i*10
   out+=f'<svg style="position:absolute;left:0;top:0;width:{width}px;height:{height}px" viewBox="0 0 340 200" fill="none"><path d="M {-30+offset} 195 C {15+offset} 130,{15+offset} 30,{120+offset} 28 S {215+offset} 185,{365+offset} 20" stroke="{color}" stroke-width="2.5"></path></svg>'
 else:
  for i in range(9):
   rw=width-25-i*24;rh=height-10-i*15
   if rw>0 and rh>0:out+=f'<div style="position:absolute;left:{(width-rw)/2}px;top:{(height-rh)/2}px;width:{rw}px;height:{rh}px;border:2px solid {color};border-radius:50%"></div>'
  out+=f'<div style="position:absolute;left:{width/2-20}px;top:0;width:40px;height:{height}px;background:{PAPER}"></div>'
 return out+'</div>'
